-- ============================================
-- LUMA — Thème 3 : LONG 1/3 x4 — Un parcours d'entretien à plusieurs étapes
-- ============================================


update scenarios set content = '{"characters": {"hr": "RH", "lead": "le chef d''équipe", "director": "le directeur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "hr", "text": "Welcome! I''m from HR, this first round is just to get to know you a bit.", "text_fr": "Bienvenue ! Je suis des RH, ce premier tour c''est juste pour apprendre à vous connaître un peu.", "choices": [{"text": "Great, I''m looking forward to it.", "text_fr": "Super, j''ai hâte.", "next": "n2"}, {"text": "Perfect, happy to share more about my background.", "text_fr": "Parfait, ravi de partager plus sur mon parcours.", "next": "n2b"}]}, "n2": {"speaker": "hr", "text": "So, what interests you most about our company culture?", "text_fr": "Alors, qu''est-ce qui vous intéresse le plus dans notre culture d''entreprise ?", "choices": [{"text": "The emphasis on collaboration really stood out to me.", "text_fr": "L''accent mis sur la collaboration m''a vraiment marqué.", "next": "n3"}, {"text": "I love that you prioritize work-life balance.", "text_fr": "J''adore que vous priorisiez l''équilibre vie pro/perso.", "next": "n3"}]}, "n2b": {"speaker": "hr", "text": "Tell me about your career journey so far.", "text_fr": "Parlez-moi de votre parcours professionnel jusqu''ici.", "choices": [{"text": "(Give a concise, well-structured career summary.)", "text_fr": "(Donne un résumé de carrière concis et bien structuré.)", "next": "n3"}]}, "n3": {"speaker": "hr", "text": "Great. How do you handle stressful situations at work?", "text_fr": "Super. Comment gérez-vous les situations stressantes au travail ?", "choices": [{"text": "I try to break big problems into smaller manageable steps.", "text_fr": "J''essaie de décomposer les gros problèmes en petites étapes gérables.", "next": "n4"}, {"text": "I take a moment to breathe, then prioritize what''s most urgent.", "text_fr": "Je prends un moment pour respirer, puis je priorise ce qui est le plus urgent.", "next": "n4"}]}, "n4": {"speaker": "hr", "text": "Good. That''s it for HR — you''ll now move to the technical round with our team lead.", "text_fr": "Bien. C''est tout pour les RH — vous allez maintenant passer au tour technique avec notre chef d''équipe.", "choices": [{"text": "Thank you, I''m ready for that.", "text_fr": "Merci, je suis prêt pour ça.", "next": "n5"}]}, "n5": {"speaker": "lead", "text": "Hi! Let''s dive into some technical scenarios. How would you handle a project with an unclear scope?", "text_fr": "Salut ! Plongeons dans quelques scénarios techniques. Comment géreriez-vous un projet au périmètre flou ?", "choices": [{"text": "I''d start by asking clarifying questions to all stakeholders.", "text_fr": "Je commencerais par poser des questions de clarification à toutes les parties prenantes.", "next": "n6"}, {"text": "I''d propose a small pilot to test assumptions before scaling.", "text_fr": "Je proposerais un petit pilote pour tester les hypothèses avant de passer à l''échelle.", "next": "n6"}]}, "n6": {"speaker": "lead", "text": "Smart approach. What''s a tool or technology you''re currently learning?", "text_fr": "Approche intelligente. Quel outil ou technologie apprenez-vous actuellement ?", "choices": [{"text": "I''ve been diving into cloud architecture recently.", "text_fr": "Je me plonge dans l''architecture cloud récemment.", "next": "n7"}, {"text": "I''m improving my data visualization skills with new tools.", "text_fr": "J''améliore mes compétences en visualisation de données avec de nouveaux outils.", "next": "n7"}]}, "n7": {"speaker": "lead", "text": "Nice. Let''s do a quick scenario — a deadline is at risk, what do you do first?", "text_fr": "Cool. Faisons un scénario rapide — un délai est en danger, vous faites quoi en premier ?", "choices": [{"text": "I''d assess exactly how much time we''re at risk of losing.", "text_fr": "J''évaluerais exactement combien de temps on risque de perdre.", "next": "n8"}, {"text": "I''d communicate the risk to stakeholders immediately, with options.", "text_fr": "Je communiquerais le risque aux parties prenantes immédiatement, avec des options.", "next": "n8"}]}, "n8": {"speaker": "lead", "text": "Good instinct. That wraps up the technical portion — you''ll now meet the department director.", "text_fr": "Bon instinct. Ça conclut la partie technique — vous allez maintenant rencontrer le directeur du département.", "choices": [{"text": "Thank you, looking forward to that conversation.", "text_fr": "Merci, j''ai hâte de cette conversation.", "next": "n9"}]}, "n9": {"speaker": "director", "text": "So, three rounds in one day — how are you holding up?", "text_fr": "Donc, trois tours en une journée — comment tenez-vous le coup ?", "choices": [{"text": "Honestly, energized! Each round has been really engaging.", "text_fr": "Honnêtement, plein d''énergie ! Chaque tour a été vraiment engageant.", "next": "n10"}, {"text": "A bit tired, but genuinely enjoying the conversations.", "text_fr": "Un peu fatigué, mais j''apprécie vraiment les conversations.", "next": "n10b"}]}, "n10": {"speaker": "director", "text": "Good to hear. Let me ask something more strategic — where do you see this industry heading?", "text_fr": "Bon à entendre. Laissez-moi poser quelque chose de plus stratégique — où voyez-vous cette industrie se diriger ?", "choices": [{"text": "I think automation will reshape a lot of the manual processes.", "text_fr": "Je pense que l''automatisation va remodeler beaucoup de processus manuels.", "next": "n11"}, {"text": "I believe sustainability will become a much bigger competitive factor.", "text_fr": "Je crois que la durabilité va devenir un facteur compétitif bien plus important.", "next": "n11"}]}, "n10b": {"speaker": "director", "text": "That''s honest, I respect that. Let''s keep this conversation light then.", "text_fr": "C''est honnête, je respecte ça. Gardons cette conversation légère alors.", "choices": [{"text": "I appreciate that, thank you.", "text_fr": "J''apprécie, merci.", "next": "n11"}]}, "n11": {"speaker": "director", "text": "(A phone rings loudly — it''s the director''s, an urgent call.) One moment, please.", "text_fr": "(Un téléphone sonne fort — c''est celui du directeur, un appel urgent.) Un instant, s''il vous plaît.", "choices": [{"text": "(Wait patiently and calmly.)", "text_fr": "(Attends patiemment et calmement.)", "next": "n12"}, {"text": "(Use the moment to jot down a thought for later.)", "text_fr": "(Profite du moment pour noter une idée pour plus tard.)", "next": "n12"}]}, "n12": {"speaker": "director", "text": "Sorry about that — unexpected urgent matter. Where were we?", "text_fr": "Désolé pour ça — un imprévu urgent. Où en étions-nous ?", "choices": [{"text": "No worries at all, we were discussing industry trends.", "text_fr": "Aucun souci, on discutait des tendances de l''industrie.", "next": "n13"}, {"text": "Take your time, I understand things come up.", "text_fr": "Prenez votre temps, je comprends que des choses arrivent.", "next": "n13"}]}, "n13": {"speaker": "director", "text": "Right. Last question — why should we choose you over other strong candidates?", "text_fr": "C''est ça. Dernière question — pourquoi devrions-nous vous choisir plutôt que d''autres candidats solides ?", "choices": [{"text": "I bring both technical skill and genuine curiosity to grow with the team.", "text_fr": "J''apporte à la fois compétence technique et curiosité sincère pour grandir avec l''équipe.", "next": "n14"}, {"text": "My track record shows I deliver results while lifting up those around me.", "text_fr": "Mon parcours montre que je livre des résultats tout en élevant ceux qui m''entourent.", "next": "n14"}]}, "n14": {"speaker": "director", "text": "That''s a strong answer. Thank you for your patience through all three rounds today.", "text_fr": "C''est une réponse forte. Merci pour votre patience à travers ces trois tours aujourd''hui.", "choices": [{"text": "Thank you for the opportunity, it''s been a great experience.", "text_fr": "Merci pour l''opportunité, ça a été une super expérience.", "next": "end_impressive"}]}, "end_impressive": {"speaker": "director", "text": "We''ll be in touch very soon — this was one of the strongest days we''ve had.", "text_fr": "On vous recontacte très bientôt — ça a été l''une des journées les plus fortes qu''on ait eues.", "end": true, "ending_label": "Parcours en 3 tours brillamment réussi 🏆"}}}'::jsonb, is_playable = true
where title = 'Un parcours d''''entretien à plusieurs étapes'
  and theme_id = (select id from scenario_themes where position = 3 and language_id = (select id from languages where code = 'en'));
